<?php
if(!defined('ABSPATH'))exit;
function bhc_image_pipeline_slots(){return ['front_3q'=>'سه‌ربع','front'=>'جلو','side'=>'کنار','back'=>'پشت','top'=>'بالا','open'=>'بازشده','detail'=>'جزئیات','in_use'=>'در محیط'];}
function bhc_image_pipeline_has_alpha($file,$mime){if(!$file||!is_readable($file)||!function_exists('imagecreatefromstring'))return null;$raw=@file_get_contents($file);$im=$raw?@imagecreatefromstring($raw):false;if(!$im)return null;$w=imagesx($im);$h=imagesy($im);$transparent=false;if(in_array($mime,['image/png','image/webp'],true)){for($x=0;$x<$w&&!$transparent;$x+=max(1,(int)($w/40)))for($y=0;$y<$h;$y+=max(1,(int)($h/40))){$rgba=imagecolorat($im,$x,$y);$alpha=($rgba>>24)&0x7F;if($alpha>0){$transparent=true;break;}}}imagedestroy($im);return $transparent;}
function bhc_image_pipeline_report($product){$slots=bhc_image_pipeline_slots();$saved=(array)get_post_meta($product->get_id(),'_bhc_angle_images',true);$rows=[];$complete=0;foreach($slots as $key=>$label){$id=absint($saved[$key]??0);$valid=$id&&wp_attachment_is_image($id);$mime=$valid?get_post_mime_type($id):'';$file=$valid?get_attached_file($id):'';$bytes=$file&&is_readable($file)?filesize($file):0;$size=$valid?wp_get_attachment_image_src($id,'full'):false;$webp=$mime==='image/webp';$alpha=$valid?bhc_image_pipeline_has_alpha($file,$mime):null;$dimensions_ok=((int)($size[1]??0)>=1200||(int)($size[2]??0)>=1200);$rows[$key]=['label'=>$label,'id'=>$id,'valid'=>$valid,'webp'=>$webp,'alpha'=>$alpha,'dimensions_ok'=>$dimensions_ok,'bytes'=>(int)$bytes,'width'=>(int)($size[1]??0),'height'=>(int)($size[2]??0),'filename'=>$valid?basename((string)$file):''];if($valid)$complete++;}return ['id'=>$product->get_id(),'name'=>$product->get_name(),'sku'=>$product->get_sku()?:'NO-SKU-'.$product->get_id(),'url'=>get_edit_post_link($product->get_id()),'rows'=>$rows,'complete'=>$complete,'total'=>count($slots)];}
add_action('admin_menu',function(){add_submenu_page('baharaan-commerce','استودیو تصاویر محصولات','استودیو تصاویر','manage_options','bhc-image-pipeline','bhc_image_pipeline_page',29);});
add_action('admin_enqueue_scripts',function(){if(sanitize_key($_GET['page']??'')==='bhc-image-pipeline')wp_enqueue_style('bhc-image-pipeline',plugin_dir_url(__FILE__).'../assets/admin.css',[],'2.9.0');});
function bhc_image_pipeline_page(){
 if(!current_user_can('manage_options')&&!current_user_can('manage_woocommerce'))return;
 $reference_import_url=wp_nonce_url(admin_url('admin-post.php?action=bhc_image_pipeline_import_references'),'bhc_image_pipeline_import_references');
 $products=function_exists('wc_get_products')?wc_get_products(['status'=>['publish','draft','pending','private'],'limit'=>-1,'orderby'=>'name','order'=>'ASC','return'=>'objects']):[];
 $reports=array_map('bhc_image_pipeline_report',$products);$total=count($reports);$ready=count(array_filter($reports,function($r){return $r['complete']===$r['total'];}));$needs=$total-$ready;$complete_views=0;$missing_views=0;$featured_missing=0;
 foreach($reports as $r){$complete_views+=(int)$r['complete'];$missing_views+=(int)($r['total']-$r['complete']);if(!has_post_thumbnail($r['id']))$featured_missing++;}
 $queued=(array)get_option('bhc_image_pipeline_queue',[]);$queue_url=wp_nonce_url(admin_url('admin-post.php?action=bhc_image_pipeline_queue'),'bhc_image_pipeline_queue');$export_url=wp_nonce_url(admin_url('admin-post.php?action=bhc_image_pipeline_export_prompts'),'bhc_image_pipeline_export_prompts');$reference_url=wp_nonce_url(admin_url('admin-post.php?action=bhc_image_pipeline_export_references'),'bhc_image_pipeline_export_references');$import_url=wp_nonce_url(admin_url('admin-post.php?action=bhc_image_pipeline_import'),'bhc_image_pipeline_import');
 echo '<section class="bhc-pipeline-panel" style="margin:16px 0;padding:16px" dir="rtl"><h2>ورود دسته‌ای مرجع تصویر</h2><p>قالب مرجع تصویر SKU را دانلود کنید و URL تصویر دقیق، مدرک تطبیق و تاریخ بررسی را تکمیل کنید. این مرحله فقط مرجع را ثبت می‌کند و تصویر را تأیید نهایی نمی‌کند.</p><form method="post" action="'.esc_url(admin_url('admin-post.php')).'" enctype="multipart/form-data"><input type="hidden" name="action" value="bhc_image_pipeline_import_references"><input type="hidden" name="_wpnonce" value="'.esc_attr(wp_create_nonce('bhc_image_pipeline_import_references')).'"><input type="file" name="reference_csv" accept=".csv,text/csv" required><button class="button button-primary" type="submit">اعتبارسنجی و ثبت مراجع</button></form></section>';
 echo '<div class="wrap bhc-image-pipeline" dir="rtl"><div class="bhc-pipeline-hero"><div><span class="bhc-eyebrow">BAHARAN IMAGE OPERATIONS</span><h1>استودیو هوشمند تصاویر محصول</h1><p>مرکز کنترل کیفیت تصاویر، گالری نماها و اتصال فایل‌های تولیدشده؛ هر عدد از داده واقعی محصولات همین فروشگاه محاسبه شده است.</p></div><div class="bhc-pipeline-actions"><a class="button button-primary" href="'.esc_url($queue_url).'">ساخت صف نماهای ناقص</a><a class="button" href="'.esc_url($reference_url).'">قالب مرجع تصویر SKU</a><a class="button" href="'.esc_url($export_url).'">دانلود پرامپت‌های SKU</a><a class="button" href="'.esc_url($import_url).'">اسکن و اتصال WebP</a></div></div><div class="bhc-pipeline-metrics"><article><b>'.esc_html(number_format_i18n($total)).'</b><span>محصول بررسی‌شده</span><small>انتشارشده، پیش‌نویس و خصوصی</small></article><article class="is-good"><b>'.esc_html(number_format_i18n($ready)).'</b><span>گالری کامل</span><small>همه '.esc_html(count(bhc_image_pipeline_slots())).' نمای استاندارد</small></article><article class="is-warn"><b>'.esc_html(number_format_i18n($needs)).'</b><span>نیازمند تکمیل</span><small>'.esc_html(number_format_i18n($missing_views)).' نمای ناقص</small></article><article class="is-info"><b>'.esc_html(number_format_i18n($featured_missing)).'</b><span>بدون تصویر شاخص</span><small>نیازمند انتخاب کاور محصول</small></article></div><section class="bhc-pipeline-panel bhc-pipeline-guide"><div><span class="bhc-section-kicker">استاندارد تولید</span><h2>چک‌لیست تصویر آماده انتشار</h2><p>نام فایل پیشنهادی <code>SKU-angle.webp</code> است. تصویر باید محصول واقعی را بدون تغییر در لوگو، فرم، دکمه‌ها یا رنگ نمایش دهد؛ ضلع بزرگ حداقل ۱۶۰۰ پیکسل، WebP و بدون واترمارک.</p></div><div class="bhc-pipeline-legend"><span><i class="is-ok"></i>تأییدشده</span><span><i class="is-missing"></i>ناقص</span><span><i class="is-review"></i>نیازمند بررسی</span></div></section><div class="bhc-pipeline-toolbar"><div><strong>وضعیت محصولات</strong><span>'.esc_html(number_format_i18n($complete_views)).' نمای معتبر از '.esc_html(number_format_i18n($total*count(bhc_image_pipeline_slots()))).'</span></div><span class="bhc-queue-pill">صف فعلی: '.esc_html(number_format_i18n(count($queued))).' نما</span></div><div class="bhc-pipeline-list">';
 foreach($reports as $report){$percent=$report['total']?(int)round($report['complete']/$report['total']*100):0;$cover=get_the_post_thumbnail_url($report['id'],'thumbnail');$status=$percent===100?'کامل':'نیازمند تکمیل';$status_class=$percent===100?'is-good':'is-warn';echo '<article class="bhc-pipeline-card"><header><div class="bhc-pipeline-product"><div class="bhc-pipeline-cover">'.($cover?'<img src="'.esc_url($cover).'" alt="'.esc_attr($report['name']).'">':'<span aria-hidden="true">◎</span>').'</div><div><span class="bhc-pipeline-sku">'.esc_html($report['sku']).'</span><h2>'.esc_html($report['name']).'</h2><em class="bhc-status '.esc_attr($status_class).'">'.esc_html($status).'</em></div></div><strong class="bhc-pipeline-score">'.esc_html($percent).'<small>%</small></strong></header><div class="bhc-pipeline-bar" aria-label="'.esc_attr($percent).'% تکمیل"><i style="width:'.esc_attr($percent).'%"></i></div><div class="bhc-pipeline-slots">';foreach($report['rows'] as $key=>$row){$state=$row['valid']?($row['webp']?'is-ok':'is-review'):'is-missing';$detail=$row['valid']?($row['webp']?'WebP · '.$row['width'].'×'.$row['height']:'فرمت نیازمند تبدیل'):'بدون تصویر';$thumb=$row['valid']?wp_get_attachment_image_url($row['id'],'thumbnail'):'';echo '<div class="bhc-pipeline-slot '.esc_attr($state).'">'.($thumb?'<img src="'.esc_url($thumb).'" alt="'.esc_attr($row['label']).'">':'<span class="bhc-slot-empty">+</span>').'<div><b>'.esc_html($row['label']).'</b><small>'.esc_html($detail).'</small></div></div>';}echo '</div><footer><a class="button button-primary" href="'.esc_url($report['url']).'">ویرایش گالری محصول</a><a class="button" href="'.esc_url(get_permalink($report['id'])).'" target="_blank" rel="noopener">مشاهده در فروشگاه</a></footer></article>';}
 if(!$reports)echo '<section class="bhc-pipeline-empty"><div class="bhc-empty-icon">✦</div><h2>هنوز محصولی برای بررسی وجود ندارد</h2><p>ابتدا یک محصول ووکامرس بسازید؛ پس از آن وضعیت تصویر شاخص و نماهای گالری در همین داشبورد نمایش داده می‌شود.</p><a class="button button-primary" href="'.esc_url(admin_url('post-new.php?post_type=product')).'">افزودن محصول جدید</a></section>';
 echo '</div></div>';
}
add_action('admin_post_bhc_image_pipeline_queue',function(){if(!current_user_can('manage_baharan_commerce'))wp_die('دسترسی مجاز نیست');check_admin_referer('bhc_image_pipeline_queue');$products=function_exists('wc_get_products')?wc_get_products(['status'=>['publish','draft','pending','private'],'limit'=>-1,'return'=>'objects']):[];$queue=[];foreach($products as $product){$report=bhc_image_pipeline_report($product);foreach($report['rows'] as $key=>$row)if(!$row['valid'])$queue[]=['product_id'=>$report['id'],'sku'=>$report['sku'],'slot'=>$key,'label'=>$row['label'],'status'=>'awaiting_reference'];}update_option('bhc_image_pipeline_queue',$queue,false);wp_safe_redirect(admin_url('admin.php?page=bhc-image-pipeline&queued='.count($queue)));exit;});
add_action('admin_post_bhc_image_pipeline_export_prompts',function(){if(!current_user_can('manage_baharan_commerce'))wp_die('دسترسی مجاز نیست');check_admin_referer('bhc_image_pipeline_export_prompts');$products=function_exists('wc_get_products')?wc_get_products(['status'=>['publish','draft','pending','private'],'limit'=>-1,'return'=>'objects']):[];$views=['front_3q'=>'front three-quarter','front'=>'straight front','side'=>'clean side profile','back'=>'rear three-quarter','top'=>'top-down','open'=>'opened state only when visible in reference','detail'=>'macro detail','in_use'=>'in-use neutral context'];nocache_headers();header('Content-Type: text/csv; charset=utf-8');header('Content-Disposition: attachment; filename=baharaan-image-prompts.csv');echo "sku,product,angle,filename,prompt\n";foreach($products as $product){$sku=$product->get_sku()?:'NO-SKU-'.$product->get_id();$safe=sanitize_file_name($sku);foreach($views as $slot=>$view){$prompt='Use the supplied verified reference image as the single source of truth for '.$product->get_name().' (SKU '.$sku.'). Create a photorealistic premium ecommerce image, '.$view.' view, exact silhouette, proportions, controls, materials, logo and model identity, centered full product, 4K, transparent background, realistic soft contact shadow, no packaging, no props, no people, no invented parts, no altered text, no watermark.';echo '"'.str_replace('"','""',$sku).'","'.str_replace('"','""',$product->get_name()).'","'.$slot.'","'.$safe.'-'.$slot.'.webp","'.str_replace('"','""',$prompt).'"'.PHP_EOL;}}exit;});
add_action('admin_post_bhc_image_pipeline_export_references',function(){if(!current_user_can('manage_baharan_commerce'))wp_die('دسترسی مجاز نیست');check_admin_referer('bhc_image_pipeline_export_references');$products=function_exists('wc_get_products')?wc_get_products(['status'=>['publish','draft','pending','private'],'limit'=>-1,'orderby'=>'name','order'=>'ASC','return'=>'objects']):[];nocache_headers();header('Content-Type: text/csv; charset=utf-8');header('Content-Disposition: attachment; filename=baharan-image-reference-register.csv');echo "sku,product,model,source_url,image_reference_url,evidence,checked_at\n";foreach($products as $product){$id=$product->get_id();$row=[$product->get_sku()?:'NO-SKU-'.$id,$product->get_name(),get_post_meta($id,'_bhc_model',true),get_post_meta($id,'_bhc_source_url',true),get_post_meta($id,'_bhc_image_reference_url',true),get_post_meta($id,'_bhc_image_reference_evidence',true),get_post_meta($id,'_bhc_image_reference_checked_at',true)];echo implode(',',array_map(function($value){return '"'.str_replace('"','""',(string)$value).'"';},$row)).PHP_EOL;}exit;});
add_action('admin_post_bhc_image_pipeline_import',function(){if(!current_user_can('manage_baharan_commerce'))wp_die('دسترسی مجاز نیست');check_admin_referer('bhc_image_pipeline_import');$uploads=wp_upload_dir();$files=[];$iterator=new RecursiveIteratorIterator(new RecursiveDirectoryIterator($uploads['basedir'],FilesystemIterator::SKIP_DOTS));foreach($iterator as $file)if($file->isFile()&&preg_match('/\.webp$/i',$file->getFilename()))$files[]=$file->getPathname();$slots=bhc_image_pipeline_slots();$imported=0;$skipped=0;foreach($files as $file){$name=pathinfo($file,PATHINFO_FILENAME);$matched=false;foreach($slots as $slot=>$label){$suffix='-'.$slot;if(substr($name,-strlen($suffix))!==$suffix)continue;$sku=substr($name,0,-strlen($suffix));if(!$sku)continue;$product_id=function_exists('wc_get_product_id_by_sku')?wc_get_product_id_by_sku($sku):0;if(!$product_id||!current_user_can('edit_post',$product_id)){ $skipped++;continue; }$mime=wp_check_filetype($file);if(($mime['type']??'')!=='image/webp'){ $skipped++;continue; }$existing=(array)get_post_meta($product_id,'_bhc_angle_images',true);$old=absint($existing[$slot]??0);if($old&&get_attached_file($old)===$file){$matched=true;break;}require_once ABSPATH.'wp-admin/includes/image.php';$attachment_id=wp_insert_attachment(['post_mime_type'=>'image/webp','post_title'=>$sku.' '.$slot,'post_status'=>'inherit','post_parent'=>$product_id],$file,$product_id);if(is_wp_error($attachment_id)){$skipped++;$matched=true;break;}wp_update_attachment_metadata($attachment_id,wp_generate_attachment_metadata($attachment_id,$file));$existing[$slot]=absint($attachment_id);update_post_meta($product_id,'_bhc_angle_images',$existing);$imported++;$matched=true;break;}if(!$matched)$skipped++;}wp_safe_redirect(admin_url('admin.php?page=bhc-image-pipeline&imported='.$imported.'&skipped='.$skipped));exit;});
add_action('admin_post_bhc_image_pipeline_convert',function(){if(!current_user_can('edit_products'))wp_die('دسترسی مجاز نیست');$product_id=absint($_GET['product_id']??0);$slot=sanitize_key($_GET['slot']??'');$attachment_id=absint($_GET['attachment_id']??0);if(!$product_id||!isset(bhc_image_pipeline_slots()[$slot])||!$attachment_id||!wp_attachment_is_image($attachment_id))wp_die('اطلاعات تصویر معتبر نیست');check_admin_referer('bhc_image_pipeline_convert_'.$product_id.'_'.$slot);$product=function_exists('wc_get_product')?wc_get_product($product_id):null;if(!$product||!current_user_can('edit_post',$product_id))wp_die('محصول معتبر نیست');$source=get_attached_file($attachment_id);if(!$source||!is_readable($source))wp_die('فایل تصویر پیدا نشد');$editor=wp_get_image_editor($source);if(is_wp_error($editor))wp_die('ویرایشگر تصویر در دسترس نیست');$uploads=wp_upload_dir();$sku=sanitize_file_name($product->get_sku()?:'product-'.$product_id);$filename=$sku.'-'.$slot.'.webp';$target=trailingslashit($uploads['path']).$filename;$saved=$editor->save($target,'image/webp');if(is_wp_error($saved))wp_die('تبدیل WebP انجام نشد');$new_id=wp_insert_attachment(['post_mime_type'=>'image/webp','post_title'=>$sku.' '.$slot,'post_status'=>'inherit','post_parent'=>$product_id],$target,$product_id);if(is_wp_error($new_id))wp_die('ثبت رسانه انجام نشد');require_once ABSPATH.'wp-admin/includes/image.php';wp_update_attachment_metadata($new_id,wp_generate_attachment_metadata($new_id,$target));$angles=(array)get_post_meta($product_id,'_bhc_angle_images',true);$angles[$slot]=absint($new_id);update_post_meta($product_id,'_bhc_angle_images',$angles);wp_safe_redirect(get_edit_post_link($product_id,'url'));exit;});
add_action('admin_notices',function(){if(sanitize_key($_GET['page']??'')!=='bhc-image-pipeline'||!current_user_can('manage_baharan_commerce'))return;$url=wp_nonce_url(admin_url('admin-post.php?action=bhc_image_pipeline_queue'),'bhc_image_pipeline_queue');$export=wp_nonce_url(admin_url('admin-post.php?action=bhc_image_pipeline_export_prompts'),'bhc_image_pipeline_export_prompts');$reference=wp_nonce_url(admin_url('admin-post.php?action=bhc_image_pipeline_export_references'),'bhc_image_pipeline_export_references');$import=wp_nonce_url(admin_url('admin-post.php?action=bhc_image_pipeline_import'),'bhc_image_pipeline_import');$queued=(array)get_option('bhc_image_pipeline_queue',[]);echo '<div class="notice notice-info"><p><strong>صف کنترل تصویر:</strong> '.esc_html(number_format_i18n(count($queued))).' نمای ناقص در صف فعلی است. <a class="button button-secondary" href="'.esc_url($url).'">بازسازی صف محصولات ناقص</a> <a class="button button-secondary" href="'.esc_url($reference).'">دانلود رجیستر مرجع تصویر</a> <a class="button button-secondary" href="'.esc_url($export).'">دانلود بسته پرامپت SKU</a> <a class="button button-primary" href="'.esc_url($import).'">اسکن و اتصال WebPهای تولیدشده</a> <span>الگوی فایل: SKU-angle.webp</span></p></div>';if(isset($_GET['queued']))echo '<div class="notice notice-success is-dismissible"><p>صف با '.esc_html(number_format_i18n(absint($_GET['queued']))).' نمای ناقص بازسازی شد.</p></div>';if(isset($_GET['imported']))echo '<div class="notice notice-success is-dismissible"><p>'.esc_html(number_format_i18n(absint($_GET['imported']))).' تصویر وارد و متصل شد؛ '.esc_html(number_format_i18n(absint($_GET['skipped']??0))).' فایل نادیده گرفته شد.</p></div>';});
add_action('admin_post_bhc_image_pipeline_import_references',function(){if(!current_user_can('manage_baharan_commerce'))wp_die('دسترسی مجاز نیست');check_admin_referer('bhc_image_pipeline_import_references');if(empty($_FILES['reference_csv']['tmp_name'])||!is_uploaded_file($_FILES['reference_csv']['tmp_name']))wp_die('فایل CSV معتبر نیست');$fh=fopen($_FILES['reference_csv']['tmp_name'],'r');$header=fgetcsv($fh);$required=['sku','product','model','source_url','image_reference_url','evidence','checked_at'];$header=array_map('trim',(array)$header);$missing=array_diff($required,$header);if($missing){fclose($fh);wp_die('ستون‌های CSV ناقص است: '.esc_html(implode(', ',$missing)));}$pos=array_flip($header);$updated=0;$rejected=0;$errors=[];$row_number=1;while(($row=fgetcsv($fh))!==false){$row_number++;$sku=sanitize_text_field($row[$pos['sku']]??'');$url=esc_url_raw($row[$pos['image_reference_url']]??'');$evidence=sanitize_textarea_field($row[$pos['evidence']]??'');$checked=sanitize_text_field($row[$pos['checked_at']]??'');$product_id=function_exists('wc_get_product_id_by_sku')?wc_get_product_id_by_sku($sku):0;$valid=$url&&wp_http_validate_url($url)&&in_array(strtolower((string)wp_parse_url($url,PHP_URL_SCHEME)),['http','https'],true)&&$evidence!==''&&$checked!=='';if(!$product_id||!$valid){$rejected++;if(count($errors)<30)$errors[]='ردیف '.$row_number.': SKU یا URL/مدرک/تاریخ نامعتبر است';continue;}update_post_meta($product_id,'_bhc_image_reference_url',$url);update_post_meta($product_id,'_bhc_image_reference_evidence',$evidence);update_post_meta($product_id,'_bhc_image_reference_checked_at',$checked);update_post_meta($product_id,'_bhc_image_generation_status','awaiting_product_reference');update_post_meta($product_id,'_bhc_catalog_quality_state','reference_needs_verification');$updated++;}fclose($fh);update_option('bhc_image_reference_import_last',['updated'=>$updated,'rejected'=>$rejected,'errors'=>$errors,'at'=>current_time('mysql')],false);wp_safe_redirect(admin_url('admin.php?page=bhc-image-pipeline&references_updated='.$updated.'&references_rejected='.$rejected));exit;});
add_action('admin_notices',function(){if(sanitize_key($_GET['page']??'')!=='bhc-image-pipeline'||!current_user_can('manage_baharan_commerce')||!isset($_GET['references_updated']))return;echo '<div class="notice notice-success is-dismissible"><p>'.esc_html(number_format_i18n(absint($_GET['references_updated']))).' مرجع تصویری ثبت شد؛ '.esc_html(number_format_i18n(absint($_GET['references_rejected']??0))).' ردیف رد شد. ثبت مرجع به‌تنهایی به‌معنی تأیید تصویر نیست.</p></div>';});
